ANCH_CODE = 125 THEN \'SNITCH - COFO - HIMAYAT NAGAR\' WHEN BRANCH_CODE = 103 THEN \'SNITCH - FOCO - SINDHUBHAVAN\' WHEN BRANCH_CODE = 18 THEN \'SNITCH - FOCO - SHYAMAL\' WHEN BRANCH_CODE = 134 THEN \'SNITCH - COCO - CG ROAD\' WHEN BRANCH_CODE = 102 THEN \'SNITCH - FOCO - BOPAL\' WHEN BRANCH_CODE = 39 THEN \'SNITCH - FOCO - VAISHALI NAGAR\' WHEN BRANCH_CODE = 91 THEN \'SNITCH - FOCO - MALVIYA NAGAR\' WHEN BRANCH_CODE = 132 THEN \'SNITCH - COCO - KAMLANAGAR\' WHEN BRANCH_CODE = 114 THEN \'SNITCH - COCO - ROHINI\' WHEN BRANCH_CODE = 40 THEN \'SNITCH - FOCO - C ROAD JODHPUR\' WHEN BRANCH_CODE = 57 THEN \'SNITCH - COCO - BANASHANKARI\' WHEN BRANCH_CODE = 14 THEN \'SNITCH - COCO - BEL ROAD\' else null end as store, m.*, uc.category_code, uc.skugroup, uc.shopify_status, uc.sku_class, uc.sales_last_7_days, uc.sales_last_15_days, uc.sales_last_30_days, uc.natural_ros, current_date as saved_date from buffermaths m left join uc on m.sku = uc.sku ;",
